// ── Linear Regression via Gradient Descent ────────────────────
// Goal: learn f(x) = w*x + b from noisy data points.
// True relationship: y ≈ 2x (with noise).

const data = [
  { x: 1, y: 2.1 }, { x: 2, y: 3.9 }, { x: 3, y: 6.2 },
  { x: 4, y: 7.8 }, { x: 5, y: 10.1 }, { x: 6, y: 12.0 },
  { x: 7, y: 13.7 }, { x: 8, y: 16.3 }
];

// ── Train / test split (80/20) ──────────────────────────────────
function trainTestSplit(dataset, testRatio = 0.2) {
  const shuffled = [...dataset].sort(() => Math.random() - 0.5);
  const testSize = Math.floor(dataset.length * testRatio);
  return {
    train: shuffled.slice(testSize),
    test:  shuffled.slice(0, testSize)
  };
}

const { train, test } = trainTestSplit(data, 0.2);
// e.g. Train: 6 examples, Test: 2 examples

// ── Gradient descent ───────────────────────────────────────────
let w = 0, b = 0;       // parameters to learn
const lr = 0.01;        // learning rate
const epochs = 2000;

function mse(dataset, w, b) {
  return dataset.reduce((sum, { x, y }) => {
    const e = (w * x + b) - y;
    return sum + e * e;
  }, 0) / dataset.length;
}

for (let epoch = 0; epoch < epochs; epoch++) {
  let gradW = 0, gradB = 0;

  for (const { x, y } of train) {
    const yHat  = w * x + b;              // forward pass
    const error = yHat - y;              // residual
    gradW += (2 / train.length) * error * x;  // dLoss/dw
    gradB += (2 / train.length) * error;      // dLoss/db
  }

  w -= lr * gradW;   // parameter update — step opposite to gradient
  b -= lr * gradB;

  if (epoch % 500 === 0) {
    const trainMSE = mse(train, w, b);
    console.log(`Epoch ${epoch}: w=${w.toFixed(3)}, b=${b.toFixed(3)}, trainMSE=${trainMSE.toFixed(4)}`);
  }
}

const finalTrainMSE = mse(train, w, b);
const finalTestMSE  = mse(test,  w, b);

console.log(`\nLearned: y ≈ ${w.toFixed(2)}x + ${b.toFixed(2)}`);
console.log(`Train MSE: ${finalTrainMSE.toFixed(4)}`);
console.log(`Test  MSE: ${finalTestMSE.toFixed(4)}`);
// Expected output (approximate):
// Learned: y ≈ 2.00x + 0.15
// Train MSE: 0.0720
// Test  MSE: 0.0890   ← slightly higher, as expected on unseen data
// If Test MSE >> Train MSE, that signals overfitting.

// ── k-Nearest Neighbours Classifier (k-NN) ────────────────────
// One of the simplest ML algorithms: classify a new point by
// majority vote among its k nearest training examples.
// No explicit 'training phase' — all work happens at prediction time.

const trainingData = [
  { features: [1, 1], label: 'cat' },
  { features: [1.5, 2], label: 'cat' },
  { features: [3, 4], label: 'dog' },
  { features: [5, 7], label: 'dog' },
  { features: [3.5, 5], label: 'dog' },
  { features: [1, 0.5], label: 'cat' }
];

function euclidean(a, b) {
  return Math.sqrt(a.reduce((sum, val, i) => sum + (val - b[i]) ** 2, 0));
}

function knnPredict(trainSet, queryPoint, k = 3) {
  // Compute distance from query to every training example
  const distances = trainSet.map(({ features, label }) => ({
    label,
    dist: euclidean(features, queryPoint)
  }));

  // Sort ascending by distance and take the k nearest
  const neighbors = distances
    .sort((a, b) => a.dist - b.dist)
    .slice(0, k);

  // Majority vote
  const votes = {};
  for (const { label } of neighbors) {
    votes[label] = (votes[label] || 0) + 1;
  }

  return Object.entries(votes)
    .sort((a, b) => b[1] - a[1])[0][0];
}

console.log(knnPredict(trainingData, [1.2, 1.5], 3)); // 'cat'
console.log(knnPredict(trainingData, [4, 6], 3));     // 'dog'
console.log(knnPredict(trainingData, [2.5, 3], 3));   // boundary region

// ── What k controls ────────────────────────────────────────────
// k=1: maximum variance — every noisy outlier affects predictions.
//      Training accuracy = 100% (it just looks itself up). Overfits.
// k=N: every point votes — collapses to the majority class. Underfits.
// k=3-10: typical sweet spot, found via validation set accuracy.

// ── Classification Metrics from Scratch ───────────────────────
// true  = actual ground-truth labels
// pred  = model's predicted labels
// positive class = 'spam'

const trueLabels = ['spam','spam','ham','ham','spam','ham','ham','spam'];
const predLabels = ['spam','ham', 'ham','ham','spam','spam','ham','spam'];

function classificationMetrics(actual, predicted, posClass) {
  let TP = 0, FP = 0, TN = 0, FN = 0;

  for (let i = 0; i < actual.length; i++) {
    const isPos   = actual[i]    === posClass;
    const predPos = predicted[i] === posClass;

    if (isPos  && predPos)  TP++;
    if (!isPos && predPos)  FP++;
    if (!isPos && !predPos) TN++;
    if (isPos  && !predPos) FN++;
  }

  const accuracy  = (TP + TN) / actual.length;
  const precision = TP / (TP + FP) || 0;
  const recall    = TP / (TP + FN) || 0;
  const f1        = precision + recall > 0
    ? 2 * (precision * recall) / (precision + recall)
    : 0;

  return { TP, FP, TN, FN, accuracy, precision, recall, f1 };
}

const m = classificationMetrics(trueLabels, predLabels, 'spam');
console.log(`Accuracy : ${(m.accuracy  * 100).toFixed(1)}%`);  // 75.0%
console.log(`Precision: ${(m.precision * 100).toFixed(1)}%`);  // 75.0%
console.log(`Recall   : ${(m.recall    * 100).toFixed(1)}%`);  // 75.0%
console.log(`F1 Score : ${(m.f1        * 100).toFixed(1)}%`);  // 75.0%
console.log(`Confusion matrix: TP=${m.TP} FP=${m.FP} TN=${m.TN} FN=${m.FN}`);

// On imbalanced data (95% negative class):
// Dummy model predicting all-negative:
//   accuracy=95%, recall=0%, precision=undefined, F1=0%
// This is why accuracy alone is insufficient for class-imbalanced problems.
